import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation for efficient membership testing of items
    with a controllable false positive rate.

    Design Choices:
    - Uses a dynamic bit array for space efficiency.
    - Implements multiple hash functions based on the input item.
    - Calculates optimal bit array size and number of hash functions based 
      on the expected items and false positive rate to minimize space 
      and maximize performance.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        if expected_items <= 0:
            raise ValueError("Expected items must be greater than 0.")
        if not (0 < false_positive_rate < 1):
            raise ValueError("False positive rate must be between 0 and 1.")

        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        self.size = self._optimal_bit_array_size()
        self.hash_count = self._optimal_number_of_hashes()
        self.bit_array = [0] * self.size

    def _optimal_bit_array_size(self) -> int:
        """Calculate optimal size of the bit array."""
        return math.ceil((-self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def _optimal_number_of_hashes(self) -> int:
        """Calculate optimal number of hash functions."""
        return math.ceil((self.size / self.expected_items) * math.log(2))

    def _hashes(self, item: str) -> list:
        """Generate hash indices for the item."""
        return [
            int(hashlib.md5(f"{item}{i}".encode()).hexdigest(), 16) % self.size
            for i in range(self.hash_count)
        ]

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for index in self._hashes(item):
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom Filter."""
        return all(self.bit_array[index] == 1 for index in self._hashes(item))

